WITH RECURSIVE x9 AS (SELECT -128 UNION SELECT DISTINCT * FROM x13) SELECT x7.v42669, x7.v42669, CONCAT_WS(REPEAT(CONCAT(x7.v42670 COLLATE latin1_swedish_ci), -208), CONCAT_WS('', CONCAT(HEX(STRCMP('9', x7.v42669))), (x7.v42670 - INTERVAL '-1941528800' DAY_MINUTE))) AS x4, x7.v42670 FROM v42668 AS x7 WHERE x7.v42670 BETWEEN 0.07 AND 1.9 AND x7.v42669 IN ('01-01-01')